# Let's use broader flight booking keywords to find candidates
flight_booking_keywords = ['book', 'booking', 'reservation', 'booked', 'reserve', 'reserv']

# Get candidate dialogs per company
candidates = {}
for d in dataset:
    dialog_lower = d['dialog'].lower()
    if any(kw in dialog_lower for kw in flight_booking_keywords):
        company = d['company_id']
        if company not in candidates:
            candidates[company] = []
        candidates[company].append(d)

print("Candidate dialogs (with booking keywords) per company:")
for company in sorted(candidates.keys()):
    print(f"  {company}: {len(candidates[company])}")

# For a fair comparison, let's sample and classify from the top companies
# We need to determine if SouthwestAir or AirAsiaSupport has more flight booking issue complaints
# Let's classify a random sample from each top company

import random
random.seed(42)

# Sample size for classification
sample_size = 50

# Get samples from top companies
top_companies = ['SouthwestAir', 'AirAsiaSupport', 'JetBlue', 'VirginAtlantic', 'AlaskaAir']
samples = {}
for company in top_companies:
    company_candidates = candidates.get(company, [])
    if len(company_candidates) > sample_size:
        samples[company] = random.sample(company_candidates, sample_size)
    else:
        samples[company] = company_candidates

print(f"\nSample sizes for classification:")
for company in top_companies:
    print(f"  {company}: {len(samples[company])}")
